node --input-type=module -e "
import pg from 'pg';
const pool = new pg.Pool({ connectionString: 'postgresql://postgres@localhost:5432/postgres' });
const q1 = async () => {
  const start = Date.now();
  await pool.query(\"SELECT * FROM app.orders WHERE user_id = 'user_42' ORDER BY created_at DESC LIMIT 10\");
  return Date.now() - start;
};
const q2 = async () => {
  const start = Date.now();
  await pool.query(\"SELECT * FROM app.orders WHERE created_at >= '2025-02-01' AND created_at < '2025-03-01' ORDER BY created_at\");
  return Date.now() - start;
};
console.log('q1 ms:', await q1());
console.log('q2 ms:', await q2());
await pool.end();
"

