      secretScanRoot: process.env.EVAL_SECRET_SCAN_ROOT ?? process.env.EVAL_WORKSPACE_ROOT ?? "/workspace",
      idempotentRerunCommand: process.env.EVAL_IDEMPOTENT_RERUN_COMMAND,
      scenario: process.env.EVAL_SCENARIO ?? "unknown",
      version: process.env.EVAL_VERSION ?? "0.0.0",
      harness: process.env.EVAL_HARNESS ?? "base-rt",
      agent: process.env.EVAL_AGENT ?? "claude-code",
      model: process.env.MODEL ?? "unknown",
      runMetadata,
      efficiency: {
        wallClockSeconds,
        agentSteps,
        tokensUsed,
        llmApiCostUsd,
        llmApiCostSource,
        inputTokens: parseNumber(process.env.EVAL_INPUT_TOKENS, 0),
        outputTokens: parseNumber(process.env.EVAL_OUTPUT_TOKENS, 0),
        cachedInputTokens: parseNumber(process.env.EVAL_CACHED_INPUT_TOKENS, 0),
        cacheCreationTokens: parseNumber(process.env.EVAL_CACHE_CREATION_TOKENS, 0),
        cacheReadTokens: parseNumber(process.env.EVAL_CACHE_READ_TOKENS, 0),
        cacheWriteTokens: parseNumber(process.env.EVAL_CACHE_WRITE_TOKENS, 0),
      },
      baselineMetrics,
      referenceMetrics,
      observedMetrics,
    });
    writeFileSync(assertionLogPath, `${JSON.stringify(assertionLogs, null, 2)}\n`, "utf8");
    process.stdout.write(`${JSON.stringify(output)}\n`);
  } finally {
    await handle.close();
  }
}

main().catch((error: unknown) => {
  const message = error instanceof Error ? error.message : String(error);
  process.stderr.write(`eval-core cli failed: ${message}\n`);
  process.exit(1);
});

