success.beforeFullFileContent:
CREATE SCHEMA IF NOT EXISTS app;

CREATE TABLE app.orders (
  order_id SERIAL PRIMARY KEY,
  user_id TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL,
  amount NUMERIC(10, 2) NOT NULL
);

INSERT INTO app.orders (user_id, created_at, amount)
SELECT
  'user_' || (random() * 1000)::int,
  -- Spread across ~2y so any fixed calendar month captures a small slice (keeps range queries fast to verify).
  '2025-01-01'::timestamptz + (random() * interval '730 days'),
  (random() * 1000)::numeric(10, 2)
FROM generate_series(1, 500000);

-- Lookups by user with sort by time (q1.sql)
CREATE INDEX idx_orders_user_id_created_at ON app.orders (user_id, created_at DESC);

-- Range filters and ordering on created_at (q2.sql)
CREATE INDEX idx_orders_created_at ON app.orders (created_at);

VACUUM ANALYZE app.orders;

